_TOKEN_RE = re.compile(
    r"""\s*(?:
          (?P<number> \d+\.\d* | \.\d+ | \d+ )
        | (?P<name>   [A-Za-z]+\d* )
        | (?P<op>     [-+*/^()] )
    )""",
    re.VERBOSE,
)


def _tokenize(src):
    """Turn a formula body into a list of (kind, text) tokens."""
    tokens = []
    pos = 0
    end = len(src)
    while pos < end:
        match = _TOKEN_RE.match(src, pos)
        if match is None:
            if src[pos:].strip() == "":
                break
            raise ValueError("unexpected character %r in %r" % (src[pos], src))
        kind = match.lastgroup
        tokens.append((kind, match.group(kind)))
        pos = match.end()
    return tokens


class _Parser:
    """Recursive-descent parser for the formula grammar.

    expr  := term (('+' | '-') term)*
    term  := unary (('*' | '/') unary)*
    unary := ('-' | '+') unary | power
    power := atom ('^' unary)?          # right-associative
    atom  := number | name | '(' expr ')'

    Putting `unary` above `power` makes unary minus bind looser than `^`
    (`-2^2` is `-(2^2)`) while still allowing `2^-3`.
    """

    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0
        self.refs = []

    def parse(self):
        node = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError("trailing input at token %d" % self._pos)
        return node

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return (None, None)

    def _accept(self, *texts):
        kind, text = self._peek()
        if kind == "op" and text in texts:
            self._pos += 1
            return text
        return None

    def _expr(self):
        node = self._term()
        while True:
            op = self._accept("+", "-")
            if op is None:
                return node
            node = ("bin", op, node, self._term())

    def _term(self):
        node = self._unary()
        while True:
            op = self._accept("*", "/")
            if op is None:
                return node
            node = ("bin", op, node, self._unary())

    def _unary(self):
        op = self._accept("-", "+")
        if op is None:
            return self._power()
        operand = self._unary()
        if op == "-":
            return ("neg", operand)
        return operand

    def _power(self):
        base = self._atom()
        if self._accept("^") is None:
            return base
        # Right-associative, and the exponent may itself be unary: 2^-3.
        return ("bin", "^", base, self._unary())

    def _atom(self):
        kind, text = self._peek()
        if kind == "number":
            self._pos += 1
            return ("num", float(text))
        if kind == "name":
            self._pos += 1
            self.refs.append(text)
            return ("ref", text)
        if kind == "op" and text == "(":
            self._pos += 1
            node = self._expr()
            if self._accept(")") is None:
                raise ValueError("expected ')'")
            return node
        if kind is None:
            raise ValueError("unexpected end of formula")
        raise ValueError("unexpected token %r" % text)


